"""Generate MonsterCN/Data/ConwayFrames.lean: frame shapes of all 167 classes of Co0."""
import json
D = json.load(open('co0_data.json'))
F = json.load(open('co0_frames.json'))
names = D['names']
out = ['''/-
# Frame shapes of all classes of Co0 (AUTO-GENERATED by `data/gen_conway_frames.py`)

`frameAll c` is the frame shape `∏ m^{a_m}` of class `c` on the 24-dimensional Leech representation,
as a list of `(m, a_m)` with `a_m ≠ 0`. It was computed from `χ₂₄` on powers in `data/co0_frames.py`,
and `MonsterCN.ConwayPowers.frames_match_chi24` re-checks it in the kernel.
-/
namespace MonsterCN.ConwayPowers
''']
out.append('def frameAll : Nat → List (Nat × Int)')
for c in range(len(names)):
    fr = sorted((int(m), k) for m, k in F['frames'][c].items())
    out.append('  | %d => [%s]  -- %s' % (c, ', '.join('(%d, %d)' % x for x in fr), names[c]))
out.append('  | _ => []')
out.append('end MonsterCN.ConwayPowers\n')
open('../MonsterCN/Data/ConwayFrames.lean', 'w', encoding='utf8').write('\n'.join(out))
idx = {n: i for i, n in enumerate(names)}
pairs = [('6E', '6J'), ('6F', '6I'), ('10D', '10I'), ('10E', '10H'), ('18D', '18G'), ('18E', '18F'), ('30F', '30K'), ('30G', '30J')]
print([(idx[a], idx[b]) for a, b in pairs])
